// Linearization point for a new SendMessage. Locks are acquired in the same
// outer-to-inner ownership order used by endpoint rebind/revocation:
// agent/runtime -> endpoint -> client -> credential. The authoritative runtime
// row is locked in this transaction so a mode/provider switch cannot race task
// creation. A management write that commits first makes this query return no
// rows; one that waits for this transaction observes the already-accepted task
// after it resumes.
func (q *Queries) LockAgentA2ASendAdmission(ctx context.Context, arg LockAgentA2ASendAdmissionParams) (LockAgentA2ASendAdmissionRow, error) {
	row := q.db.QueryRow(ctx, lockAgentA2ASendAdmission,
		arg.AgentID,
		arg.WorkspaceID,
		arg.EndpointID,
		arg.PublicAgentID,
		arg.ClientID,
		arg.CredentialID,
	)
	var i LockAgentA2ASendAdmissionRow
	err := row.Scan(
		&i.EndpointID,
		&i.WorkspaceID,
		&i.AgentID,
		&i.PublicAgentID,
		&i.CardName,
		&i.DelegatedByUserID,
		&i.AgentRuntimeID,
		&i.ClientID,
		&i.CredentialID,
	)
	return i, err
}

